## Why This Is Asked

This problem tests advanced dynamic programming: partitioning with a non-trivial segment cost that depends on min and max, requiring careful state design and in-loop maintenance of subproblem results. It also validates producing both memoized and iterative solutions and analyzing time/space trade-offs.

## Key Concepts

- DP with partition states
- In-loop maintenance of running min and max
- Top-down memoization vs bottom-up tabulation
- Time complexity: O(D*N^2); Space: O(D*N)

## Code Example

```javascript
// Top-down memoized
function minCost(A, D){
  const N = A.length;
  const memo = Array.from({length:D+1}, ()=> Array(N).fill(null));
  function solve(d, i){
    if (d === 1){
      let mn = Infinity, mx = -Infinity;
      for (let k = 0; k <= i; k++){ mn = Math.min(mn, A[k]); mx = Math.max(mx, A[k]); }
      return mn * mx;
    }
    if (memo[d][i] != null) return memo[d][i];
    let mn = Infinity, mx = -Infinity; let best = Infinity;
    for (let j = i; j >= d-1; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      best = Math.min(best, solve(d-1, j-1) + mn*mx);
    }
    memo[d][i] = best; return best;
  }
  return solve(D, N-1);
}

// Bottom-up
function minCostBottom(A, D){
  const N = A.length, INF = 1e18;
  const dp = Array.from({length:D+1}, ()=> Array(N).fill(INF));
  // base: d = 1
  for (let i = 0; i < N; i++){
    let mn = A[i], mx = A[i];
    for (let j = i; j >= 0; j--){
      mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
      if (j === 0) dp[1][i] = Math.min(dp[1][i], mn*mx);
    }
  }
  for (let d = 2; d <= D; d++){
    for (let i = d-1; i < N; i++){
      let mn = A[i], mx = A[i];
      for (let j = i; j >= d-1; j--){
        mn = Math.min(mn, A[j]); mx = Math.max(mx, A[j]);
        dp[d][i] = Math.min(dp[d][i], dp[d-1][j-1] + mn*mx);
      }
    }
  }
  return dp[D][N-1];
}
```

## Why This Question Is Asked
This question tests dynamic programming intuition on a constrained path counting problem with simple transitions and boundary conditions.

## Key Concepts
- **Recurrence relation:** f(i) = f(i+1) + f(i+2) with modulo arithmetic
- **Memoization vs. tabulation:** Trade-offs between recursive top-down with caching versus iterative bottom-up approaches
- **Edge conditions:** Blocked start/end positions, single-cell arrays

## Code Example
```javascript
function countPaths(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  // Memoized DFS
  const memo = Array(n).fill(-1);
  function dfs(i) {
    if (i === n - 1) return blocked[i] ? 0 : 1;
    if (i >= n || blocked[i]) return 0;
    if (memo[i] !== -1) return memo[i];
    memo[i] = (dfs(i + 1) + dfs(i + 2)) % MOD;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up DP (O(1) space)
function countPathsDP(blocked) {
  const n = blocked.length;
  const MOD = 1000000007;
  if (blocked[0]) return 0;

  let next2 = 1, next1 = blocked[n - 1] ? 0 : 1;
  for (let i = n - 2; i >= 0; i--) {
    const curr = blocked[i] ? 0 : (next1 + next2) % MOD;
    next2 = next1;
    next1 = curr;
  }
  return next1;
}
```

